"""Word-count utilities for the wordstats mock project."""


def count_words(text):
    """Return a mapping of lowercased words to occurrence counts.

    Punctuation is stripped from token edges; tokens that are only
    punctuation are ignored.
    """
    counts = {}
    for raw in text.lower().split():
        word = raw.strip(".,;:!?-\"'()")
        if word:
            counts[word] = counts.get(word, 0) + 1
    return counts

"""Focused unit tests for wordstats.counter."""

import unittest

from wordstats.counter import count_words


class CountWordsTests(unittest.TestCase):
    def test_counts_basic_words(self):
        self.assertEqual(count_words("apple banana apple"), {"apple": 2, "banana": 1})

    def test_strips_punctuation_and_lowercases(self):
        self.assertEqual(count_words("Apple! apple, BANANA."), {"apple": 2, "banana": 1})

    def test_ignores_punctuation_only_tokens(self):
        self.assertEqual(count_words("-- ..."), {})

    def test_empty_input(self):
        self.assertEqual(count_words(""), {})


if __name__ == "__main__":
    unittest.main()

"""Summary statistics over a word-count mapping."""

import statistics


def summarize_counts(counts):
    """Return {min, max, median, unique} for a counts mapping.

    Even-count median is the mean of the two middle values; empty input
    yields {max: 0, median: 0, min: 0, unique: 0}.
    """
    if not counts:
        return {"min": 0, "max": 0, "median": 0, "unique": 0}
    values = list(counts.values())
    return {
        "min": min(values),
        "max": max(values),
        "median": statistics.median(values),
        "unique": len(values),
    }

"""Count-summary statistics for the wordstats count CLI."""

import statistics


def summarize_counts(counts):
    """Return min/max/median of the count values plus the unique word count.

    The returned mapping has keys `min`, `max`, `median`, and `unique`;
    `unique` is the number of distinct words (length of the mapping).
    `min`, `max`, and `median` are `None` when `counts` is empty, and the
    median of an even number of values is the average of the two middle
    values. The input mapping is not mutated.
    """
    values = list(counts.values())
    if not values:
        return {"min": None, "max": None, "median": None, "unique": 0}
    return {
        "min": min(values),
        "max": max(values),
        "median": statistics.median(values),
        "unique": len(counts),
    }

